mapper.select:
select count(*)
from PLACE
where place_id = #{placeId}
  and member_id = #{memberId}

mapper.insert:
insert into PLACE_IMAGE (place_id, image_url, sort_order)
values (
    #{placeId},
    #{imageUrl},
    (select next_order
     from (
         select coalesce(max(pi.sort_order), -1) + 1 as next_order
         from PLACE_IMAGE pi
         where pi.place_id = #{placeId}
     ) image_order)
)
